    tips: ["Scotch Bonnet ist typisch – Menge nach Schärfetoleranz.", "Piment (Allspice) ist das unverzichtbare Jerk-Gewürz.", "Über Rauch grillen für das authentische Aroma."],
    proTip: "Piment (Allspice) und Scotch Bonnet sind das Rückgrat von Jerk – ohne sie ist es nur scharfes Grillfleisch. Das langsame Garen über Rauch macht daraus den echten jamaikanischen Klassiker.",
