    proTip: "Den Fisch überwiegend auf der Hautseite garen und mehrfach mit der Aprikosen-Butter bestreichen – die Haut hält den Fisch zusammen und die Glasur karamellisiert schichtweise zur typischen süß-rauchigen Kruste.",
    learn: ["Fisch aufklappen", "Aprikosen-Basting", "Auf der Haut grillen", "Schichtweise glasieren"],
